CREATE TABLE public.finance_workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), capability_hash text UNIQUE, transactions jsonb NOT NULL DEFAULT '[]', budgets jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.finance_workspaces TO service_role;
ALTER TABLE public.finance_workspaces ENABLE ROW LEVEL SECURITY;
